import {scale,canConnect,faults} from './engine.js';
const btn=(label,action,active=false,extra='')=>`<button class="bench-button ${active?'active':''}" data-act="${action}" ${extra}>${label}</button>`;
const toggle=(name,action,on)=>`<button class="switch ${on?'on':''}" data-act="${action}" aria-pressed="${on}"><span><small>${action==='a'?'X0':action==='b'?'X1':'SIGNAL'}</small>${name}</span><span class="switch-track"><i></i></span><b>${on?'ON':'OFF'}</b></button>`;
const stat=(label,value,on=false)=>`<div class="stat ${on?'lit':''}"><small>${label}</small><strong>${value}</strong></div>`;
const select=(label,key,options,value)=>`<label class="field">${label}<select data-field="${key}">${options.map(([v,t])=>`<option value="${v}" ${value===v?'selected':''}>${t}</option>`).join('')}</select></label>`;
const num=(label,key,value,min=0,max=1000)=>`<label class="field">${label}<input type="number" min="${min}" max="${max}" step="1" value="${value}" data-field="${key}"></label>`;
const mark=(label,done)=>`<li class="${done?'checked':''}"><span>${done?'✓':'○'}</span>${label}</li>`;
const note=t=>`<p class="bench-note">${t}</p>`;
export function rung(s){
 const c=(x,y,label,inverted,on)=>`<g stroke="${on?'#92e8b8':'#60747b'}" stroke-width="3"><path d="M${x-12} ${y-16}v32 M${x+12} ${y-16}v32"/>${inverted?`<path d="M${x-18} ${y+20}l36 -40"/>`:''}</g><text x="${x}" y="${y-29}" text-anchor="middle" fill="#e7f1ee" font-size="16">${label}</text>`;
 const tA=s.notA?!s.a:s.a,tB=s.notB?!s.b:s.b;
 return `<svg class="ladder" viewBox="0 0 500 200" role="img" aria-label="${s.mode} ladder rung. A ${s.a?'on':'off'}, B ${s.b?'on':'off'}, output ${s.out?'on':'off'}."><g stroke="#60747b" fill="none" stroke-width="2"><path d="M25 30v140 M475 30v140 M25 80H108 M132 80H258 M282 80H408 M442 80h33"/>${s.mode==='OR'?'<path d="M65 80v65h43 M132 145H350V80 M132 80h276"/>':''}<path d="M419 63q-18 17 0 34 M431 63q18 17 0 34" stroke="${s.out?'#92e8b8':'#60747b'}"/></g>${c(120,80,'A',s.notA,tA)}${s.mode==='AND'?c(270,80,'B',s.notB,tB):c(120,145,'B',s.notB,tB)}<text x="425" y="45" text-anchor="middle" fill="#e7f1ee" font-size="16">Y0</text><text x="425" y="134" text-anchor="middle" fill="${s.out?'#92e8b8':'#9aaeb3'}" font-size="13">${s.out?'ON':'OFF'}</text></svg>`;
}
export function renderLab(s){
 let html='';
 switch(s.i){
 case 0:html=`<div class="signal-diagram"><span>INPUT<big>Sensor</big></span><i>→</i><span class="plc-chip">PLC<big>Evaluate</big></span><i>→</i><span>OUTPUT<big class="${s.out?'green':''}">${s.out?'Lamp on':'Lamp off'}</big></span></div>${toggle('Object detected','a',s.a)}<div class="stats">${stat('INPUT MEMORY',s.a?'TRUE':'FALSE',s.a)}${stat('OUTPUT Y0',s.out?'ON':'OFF',s.out)}${stat('SCANS',s.scans)}</div><div class="bench-actions">${btn('Step scan','scan')}</div>${note('The switch changes the input. Step scan evaluates the program. This model stays paused between scans.')}<ul class="bench-checks">${mark('Observed output on after a scan',s.seenOn)}${mark('Observed output off after a scan',s.seenOff)}</ul>`;break;
 case 1:{const cards=['Start button signal to PLC','Valve open command from PLC','Tank level measurement to PLC','Alarm lamp command from PLC','Motor running feedback to PLC','Drive run command from PLC'];html=`<div class="io-cards">${cards.map((x,i)=>select(`${i+1}. ${x}`,'map'+i,[['','Choose direction'],['Input','PLC input'],['Output','PLC output']],s.map[i])).join('')}</div>${note('Always classify from the controller’s point of view. Direction, not the device’s size, determines the group.')}`;break;}
 case 2:html=`${rung(s)}<div class="field-row">${select('Arrangement','mode',[['AND','Series'],['OR','Parallel']],s.mode)}<button class="bench-button" aria-pressed="${s.notA}" data-act="notA">A: ${s.notA?'inverted test':'true test'}</button><button class="bench-button" aria-pressed="${s.notB}" data-act="notB">B: ${s.notB?'inverted test':'true test'}</button></div><div class="field-row">${toggle('Permission A','a',s.a)}${toggle('Permission B','b',s.b)}</div>${note('Every control change evaluates the rung. Check practice tests all four combinations against the requirement.')}`;break;
 case 3:html=`${select('Combine the required permissions','mode',[['OR','Either permission'],['AND','Every permission']],s.mode)}<div class="field-row">${toggle('StopHealthy','stop',s.stop)}${toggle('OverloadHealthy','overload',s.overload)}</div><div class="stats">${stat('START REQUEST',s.start?'HELD':'RELEASED',s.start)}${stat('RUN REQUEST',s.run?'ON':'OFF',s.run)}</div><div class="bench-actions">${btn('Press Start','start',s.start)}${btn('Release Start','release')}</div><ul class="bench-checks">${['Start with both permissions present','Release Start and retain the request','Remove StopHealthy and stop','Restore StopHealthy, start, then remove OverloadHealthy','With StopHealthy off, press Start and remain stopped'].map((x,i)=>mark(x,s.motorChecks[i])).join('')}</ul>${note('Every action evaluates one scan. Run request is simulated; it does not prove actual motor motion.')}`;break;
 case 4:html=`<div class="field-row">${num('Preset in seconds','preset',s.preset,1,20)}${toggle('Timer Enable','enable',s.enable)}</div><div class="timer-face"><span>${s.elapsed.toFixed(1)}<small> / ${s.preset} s</small></span><div class="bar"><i style="width:${Math.min(100,s.elapsed/Math.max(.1,s.preset)*100)}%"></i></div></div><div class="stats">${stat('ENABLE',s.enable?'TRUE':'FALSE',s.enable)}${stat('DONE',s.done?'TRUE':'FALSE',s.done)}</div><div class="bench-actions">${btn('Advance 0.5 seconds','advance')}</div>${note('Time here is simulated: each press advances half a second. Disabling this nonretentive timer resets its accumulated time.')}<ul class="bench-checks">${mark('Reached Done at the required preset',s.timerDone)}${mark('Disabled and observed reset',s.timerReset)}</ul>`;break;
 case 5:html=`${select('Increment the counter','countMode',[['level','Each scan while input is on'],['edge','On each rising edge']],s.countMode)}${toggle('Part sensor','a',s.a)}<div class="stats">${stat('PART COUNT',s.count)}${stat('BATCH OF 5',s.out?'COMPLETE':'IN PROGRESS',s.out)}${stat('SCANS',s.scans)}</div><div class="bench-actions">${btn('Step another scan','scan')}${btn('Reset count','countReset')}</div><ul class="bench-checks">${mark('Held input stayed at one count over two extra scans',s.heldChecks>=2)}${mark('Reached five events',s.maxCount>=5)}${mark('Reset after the batch',s.counterReset)}</ul>${note('Changing the sensor executes a scan. An extra scan leaves the input unchanged. Changing counting mode starts a new test.')}`;break;
 case 6:html=`<div class="state-track">${['Idle','Fill','Mix','Drain'].map((x,i)=>`<span class="${s.state===x?'current':''}"><small>0${i}</small>${x}</span>`).join('')}</div><div class="stats">${stat('INLET',s.state==='Fill'?'ON':'OFF',s.state==='Fill')}${stat('MIXER',s.state==='Mix'?'ON':'OFF',s.state==='Mix')}${stat('OUTLET',s.state==='Drain'?'ON':'OFF',s.state==='Drain')}</div><div class="field-row">${toggle('High level','high',s.high)}${toggle('Mix complete','mixDone',s.mixDone)}${toggle('Low level','low',s.low)}</div><div class="bench-actions">${btn('Start cycle','start')}${btn('Step scan','scan')}${btn('Stop / return to Idle','seqStop')}</div>${note('A sensor toggle changes memory. Step scan tests the transition. Start begins a fresh cycle and clears the simulated sensors.')}<ul class="bench-checks">${mark('Waited without completion in Fill, Mix, and Drain',['Fill','Mix','Drain'].every(x=>s.waited.includes(x)))}${mark('Completed the sequence',s.cycleDone)}${mark('Tested Stop',s.seqStopped)}</ul>`;break;
 case 7:{const n=scale(s.raw,s.rawLow,s.rawHigh,s.engLow,s.engHigh),trusted=s.valid&&s.rawHigh>s.rawLow&&s.raw>=s.rawLow&&s.raw<=s.rawHigh;html=`<div class="field-row">${num('Raw low','rawLow',s.rawLow)}${num('Raw high','rawHigh',s.rawHigh)}${num('Liters low','engLow',s.engLow)}${num('Liters high','engHigh',s.engHigh)}</div><label class="range-label">Raw input <b>${s.raw}</b><input type="range" min="0" max="1000" step="50" value="${s.raw}" data-field="raw"></label><div class="stats">${stat('RAW',s.raw)}${stat('MEASUREMENT',trusted?n.toFixed(1)+' L':'INVALID',trusted)}</div>${toggle('Signal valid','valid',s.valid)}<div class="bench-actions">${btn('Record this sample','sample')}</div>${note('Recorded raw samples: '+(s.analogSamples.length?s.analogSamples.join(', '):'none yet')+'. Invalid measurements are not presented as a trustworthy tank level.')}`;break;}
 case 8:html=`<div class="hmi-screen"><div class="hmi-top"><span>FILL STATION</span><i class="${s.comms?'green':'amber'}">${s.comms?'CONNECTED':'COMMUNICATION LOST'}</i></div><div class="hmi-status">${!s.comms?'Status unavailable':s.run?'Running':'Stopped'}</div><div class="alarm ${s.latched?'alarm-on':''}">${!s.comms?'Current alarm status unavailable':s.latched?`Level signal fault · ${s.ack?'Acknowledged':'Needs acknowledgement'} · ${s.fault?'Cause active':'Cause cleared'}`:'No latched alarm'}</div><div class="bench-actions">${btn('Start','hmiStart')}${btn('Stop','hmiStop')}${btn('Acknowledge','ack')}${btn('Reset fault','hmiReset')}</div></div><div class="bench-actions">${btn(s.fault?'Remove fault cause':'Inject sensor fault','fault',s.fault)}${btn(s.comms?'Disconnect screen':'Reconnect screen','comms',!s.comms)}</div>${note('PLC control buttons on the screen are unavailable while disconnected. Fault injection represents the process, independent of the screen.')}<ul class="bench-checks">${mark('Started, faulted, and acknowledged',s.hmiStage>=3)}${mark('Attempted reset while the cause was active',s.hmiStage>=4)}${mark('Removed cause and reset without starting',s.hmiStage>=5&&!s.run)}</ul>`;break;
 case 9:html=`<div class="network-cards"><div><h3>Practice computer</h3><p>192.168.<b>${s.pcSubnet}.${s.pcHost}</b> /24</p>${num('Subnet number','pcSubnet',s.pcSubnet,0,255)}${num('Host number','pcHost',s.pcHost,1,254)}</div><div><h3>Virtual PLC</h3><p>192.168.<b>${s.plcSubnet}.${s.plcHost}</b> /24</p>${num('Subnet number','plcSubnet',s.plcSubnet,0,255)}${num('Host number','plcHost',s.plcHost,1,254)}</div></div><div class="stats">${stat('SESSION',s.connected?'ONLINE':'OFFLINE',s.connected)}${stat('BACKUP',s.backup?'SAVED':'NONE',!!s.backup)}</div><div class="bench-actions">${btn('Try connection','connect')}${btn('Save configuration','backup',false,s.connected?'':'disabled')}${btn('Restore saved configuration','restore',false,s.backup?'':'disabled')}</div>${note('This is a network model. No actual network connection is made. Addresses must be different hosts in the same /24 subnet.')}<ul class="bench-checks">${mark('Restored after a configuration change',s.restored)}</ul>`;break;
 case 10:{const f=faults[s.faultCase];html=`<p class="case-number">CASE ${s.faultCase+1} OF 3</p><h3 class="case-title">${f.title}</h3><div class="evidence-grid">${['Field condition','PLC input','Program logic','Output and device'].map((x,i)=>`<button data-act="inspect" data-value="${i}" class="evidence ${s.inspected.includes(i)?'open':''}"><small>0${i+1} · ${x}</small><span>${s.inspected.includes(i)?f.evidence[i]:'Inspect evidence →'}</span></button>`).join('')}</div>${select('Where is the first mismatch?','diagnosis',[['','Choose after inspecting'],['Input signal path','Input signal path'],['Program condition','Program condition'],['Output device path','Output device path']],s.diagnosis)}${s.diagnosed>s.faultCase&&s.faultCase<2?`<div class="bench-actions">${btn('Open next case','nextFault')}</div>`:''}${note('Check practice evaluates your diagnosis. A correct case opens the next investigation; finish all three to complete the lab.')}`;break;}
 case 11:html=`<div class="field-row">${num('Target level %','target',s.target,10,90)}${num('Timeout seconds','timeout',s.timeout,1,30)}</div><button class="policy ${s.fresh?'enabled':''}" data-act="fresh" aria-pressed="${s.fresh}"><span>Restart policy</span><b>${s.fresh?'Require release and fresh Start':'Accept a held Start request'}</b></button><div class="plant"><div class="tank"><div class="water" style="height:${s.level}%"></div><span>${s.valid?s.level.toFixed(0)+'%':'INVALID'}</span><i style="bottom:${s.target}%"></i></div><div class="plant-readings">${stat('STATE',s.fillState,s.out)}${stat('FILL TIME',s.fillElapsed.toFixed(1)+' s')}${stat('CYCLES',s.fillCount)}</div></div>${s.fillFault?`<div class="alarm alarm-on">${s.fillFault}</div>`:note(s.fillReason||'Ready for your test.')}<div class="bench-actions">${btn('Press Start','fillStart',s.start)}${btn('Release Start','fillRelease')}${btn('Advance 0.5 seconds','advance')}${btn('Reset cycle','fillReset')}${btn('Restart controller','restart')}</div><div class="field-row">${toggle('Run permission','stop',s.stop)}${toggle('Signal valid','valid',s.valid)}${toggle('Freeze level','frozen',s.frozen)}</div>${note('Reset requires Start released, a valid signal, and run permission. Restart preserves the simulated physical level. Time advances only when requested.')} ${s.report?`<ul class="bench-checks report">${s.report.map(([x,ok])=>mark(x,ok)).join('')}</ul>`:''}`;break;
 }
 if(s.i===8&&!s.comms)for(const action of ['hmiStart','hmiStop','ack','hmiReset'])html=html.replace(`data-act="${action}"`,`data-act="${action}" disabled`);
 return `<div class="bench-top"><span class="live-dot"></span>PLC TRAINING BENCH<span class="bench-mode">SIMULATED · NO EQUIPMENT</span></div><div class="bench-body">${html}</div>`;
}
